algorithm LargestOfSeries
    define count as integer;
    define i as integer;
    define number as integer;
    define largest as integer;
    read count;
    read largest;
    for i <- 2 to count step 1 do
        read number;
        if number > largest then
            largest <- number;
        endIf
    endFor
    write largest;
endAlgorithm
